#!/usr/bin/env bash
# Populate private/credentials.env from credentials generated by this local stack.
# Values are never printed. External provider credentials remain user supplied.
set -euo pipefail

ROOT_DIR="$(cd -- "$(dirname -- "$0")/../.." && pwd)"
CREDENTIALS_FILE="$ROOT_DIR/private/credentials.env"

mkdir -p "$ROOT_DIR/private"
chmod 700 "$ROOT_DIR/private"
if [[ ! -f "$CREDENTIALS_FILE" ]]; then
  cp "$ROOT_DIR/credentials.env.example" "$CREDENTIALS_FILE"
fi
chmod 600 "$CREDENTIALS_FILE"

set_credential() {
  local key="$1" value="$2" tmp line found=0
  [[ -n "$value" ]] || return 0
  tmp="$(mktemp "$ROOT_DIR/private/.credentials.XXXXXX")"
  while IFS= read -r line || [[ -n "$line" ]]; do
    if [[ "$line" == "$key="* ]]; then
      printf '%s=' "$key" >> "$tmp"
      printf '%q\n' "$value" >> "$tmp"
      found=1
    else
      printf '%s\n' "$line" >> "$tmp"
    fi
  done < "$CREDENTIALS_FILE"
  if (( found == 0 )); then
    printf '%s=' "$key" >> "$tmp"
    printf '%q\n' "$value" >> "$tmp"
  fi
  chmod 600 "$tmp"
  mv "$tmp" "$CREDENTIALS_FILE"
}

credential_value() {
  local key="$1" value
  value="$(sed -nE "s/^${key}=(.*)$/\1/p" "$CREDENTIALS_FILE" | head -n 1)"
  if [[ "$value" == "'"*"'" ]]; then value="${value:1:${#value}-2}"; fi
  printf '%s' "$value"
}

xml_value() {
  local file="$1" tag="$2"
  [[ -f "$file" ]] || return 0
  sed -nE "s|.*<$tag>([^<]+)</$tag>.*|\1|p" "$file" | head -n 1
}

json_api_key() {
  local file="$1"
  [[ -f "$file" ]] || return 0
  sed -nE 's/.*"apiKey"[[:space:]]*:[[:space:]]*"([^"]+)".*/\1/p' "$file" | head -n 1
}

set_credential PLEX_AUTH_METHOD browser_oauth

# The VPN application's OAuth/session token remains in its own secure storage.
# MovieNook records only the selected provider and login mechanism here.
if [[ -n "${MOVIENOOK_VPN_PROVIDER:-}" ]]; then
  set_credential VPN_PROVIDER "$MOVIENOOK_VPN_PROVIDER"
fi
if [[ -n "${MOVIENOOK_VPN_AUTH_METHOD:-}" ]]; then
  set_credential VPN_AUTH_METHOD "$MOVIENOOK_VPN_AUTH_METHOD"
fi

set_credential RADARR_API_KEY "$(xml_value "$ROOT_DIR/config/radarr/config.xml" ApiKey)"
set_credential SONARR_API_KEY "$(xml_value "$ROOT_DIR/config/sonarr/config.xml" ApiKey)"
set_credential PROWLARR_API_KEY "$(xml_value "$ROOT_DIR/config/prowlarr/config.xml" ApiKey)"
set_credential SEERR_API_KEY "$(json_api_key "$ROOT_DIR/config/seerr/settings.json")"

plex_preferences="$ROOT_DIR/config/plex/Library/Application Support/Plex Media Server/Preferences.xml"
if [[ -f "$plex_preferences" ]]; then
  plex_token="$(sed -nE 's/.*PlexOnlineToken="([^"]+)".*/\1/p' "$plex_preferences" | head -n 1)"
  if [[ -n "$plex_token" ]]; then
    account="$(curl --fail --silent --show-error --header "X-Plex-Token: $plex_token" --header 'Accept: application/json' https://plex.tv/users/account.json || true)"
    set_credential PLEX_USERNAME "$(printf '%s' "$account" | sed -nE 's/.*"username"[[:space:]]*:[[:space:]]*"([^"]*)".*/\1/p')"
    set_credential PLEX_EMAIL "$(printf '%s' "$account" | sed -nE 's/.*"email"[[:space:]]*:[[:space:]]*"([^"]*)".*/\1/p')"
    unset account plex_token
  fi
fi

if [[ -f "$ROOT_DIR/config/sabnzbd/sabnzbd.ini" ]]; then
  set_credential SABNZBD_API_KEY "$(awk -F= '/^[[:space:]]*api_key[[:space:]]*=/{sub(/^[^=]*=[[:space:]]*/, ""); print; exit}' "$ROOT_DIR/config/sabnzbd/sabnzbd.ini")"
  set_credential SABNZBD_USERNAME "$(awk -F= '/^[[:space:]]*username[[:space:]]*=/{sub(/^[^=]*=[[:space:]]*/, ""); print; exit}' "$ROOT_DIR/config/sabnzbd/sabnzbd.ini")"
  set_credential SABNZBD_PASSWORD "$(awk -F= '/^[[:space:]]*password[[:space:]]*=/{sub(/^[^=]*=[[:space:]]*/, ""); print; exit}' "$ROOT_DIR/config/sabnzbd/sabnzbd.ini")"
fi

qbit_password="$(credential_value QBITTORRENT_PASSWORD)"
if [[ -z "$qbit_password" ]] && docker ps --format '{{.Names}}' | grep -qx movienook-qbittorrent; then
  qbit_password="$(od -An -N18 -tx1 /dev/urandom | tr -d ' \n')"
  qbit_hash="$(docker exec -e MOVIENOOK_QBIT_PASSWORD="$qbit_password" movienook-seerr node -e '
    const crypto = require("crypto");
    const salt = crypto.randomBytes(16);
    const hash = crypto.pbkdf2Sync(process.env.MOVIENOOK_QBIT_PASSWORD, salt, 100000, 64, "sha512");
    process.stdout.write(`@ByteArray(${salt.toString("base64")}:${hash.toString("base64")})`);
  ')"
  qbit_conf="$ROOT_DIR/config/qbittorrent/qBittorrent/qBittorrent.conf"
  mkdir -p "$ROOT_DIR/private/backups"
  cp "$qbit_conf" "$ROOT_DIR/private/backups/qBittorrent.conf-before-password"
  docker stop movienook-qbittorrent >/dev/null
  qbit_tmp="$(mktemp "$ROOT_DIR/private/.qbit-conf.XXXXXX")"
  awk -v hash="$qbit_hash" '
    BEGIN { done=0 }
    /^WebUI\\Password_PBKDF2=/ { print "WebUI\\Password_PBKDF2=\"" hash "\""; done=1; next }
    { print }
    END { if (!done) print "WebUI\\Password_PBKDF2=\"" hash "\"" }
  ' "$qbit_conf" > "$qbit_tmp"
  chmod 644 "$qbit_tmp"
  mv "$qbit_tmp" "$qbit_conf"
  docker start movienook-qbittorrent >/dev/null
  set_credential QBITTORRENT_USERNAME admin
  set_credential QBITTORRENT_PASSWORD "$qbit_password"
  unset qbit_hash qbit_conf qbit_tmp
fi
unset qbit_password

qbit_conf="$ROOT_DIR/config/qbittorrent/qBittorrent/qBittorrent.conf"
if [[ -f "$qbit_conf" ]] && grep -qE '=(/downloads/|/downloads/incomplete/)$' "$qbit_conf"; then
  mkdir -p "$ROOT_DIR/private/backups"
  cp "$qbit_conf" "$ROOT_DIR/private/backups/qBittorrent.conf-before-paths"
  docker stop movienook-qbittorrent >/dev/null
  qbit_tmp="$(mktemp "$ROOT_DIR/private/.qbit-conf.XXXXXX")"
  sed \
    -e 's|=/downloads/incomplete/$|=/data/downloads/torrents/incomplete/|' \
    -e 's|=/downloads/$|=/data/downloads/torrents/|' \
    "$qbit_conf" > "$qbit_tmp"
  chmod 644 "$qbit_tmp"
  mv "$qbit_tmp" "$qbit_conf"
  docker start movienook-qbittorrent >/dev/null
  unset qbit_conf qbit_tmp
fi

echo 'Local credentials synchronized privately.'
if [[ -z "$(credential_value INDEXER_1_API_KEY)" && -z "$(credential_value INDEXER_1_URL)" ]]; then
  echo 'Setup note: add at least one indexer account to private/credentials.env before downloads can be found.'
fi
